1	//! The remote port's adapters: the identity and device files on disk,
2	//! the host's certificate and key, and the TLS listener that carries
3	//! requests from paired devices to the frame.
4	//!
5	//! The listener has the control socket's shape: one accept thread, one
6	//! thread per connection, every request handed to the frame over a
7	//! bounded channel and answered there. What the frame decides (who the
8	//! bearer is, what the path means, what leaves redacted) lives in
9	//! `app.rs`; this file only moves bytes and enforces the bounds that
10	//! need no state: pools, deadlines and rate limits.
11	
12	use std::collections::VecDeque;
13	use std::fmt::Write as _;
14	use std::io::{self, BufRead, BufReader, Read, Write};
15	use std::net::{IpAddr, SocketAddr, TcpListener, TcpStream, UdpSocket};
16	use std::path::PathBuf;
17	use std::sync::atomic::{AtomicBool, AtomicU64, AtomicUsize, Ordering};
18	use std::sync::mpsc::{self, Receiver, SyncSender};
19	use std::sync::{Arc, Mutex};
20	use std::thread::JoinHandle;
21	use std::time::{Duration, Instant, SystemTime};
22	
23	use base64::Engine as _;
24	use rcgen::PublicKeyData as _;
25	use rustls::client::danger::{HandshakeSignatureValid, ServerCertVerified, ServerCertVerifier};
26	use rustls::crypto::CryptoProvider;
27	use rustls::pki_types::{CertificateDer, PrivateKeyDer, PrivatePkcs8KeyDer, ServerName, UnixTime};
28	use rustls::{
29	    ClientConfig, DigitallySignedStruct, ServerConfig, ServerConnection, SignatureScheme,
30	    StreamOwned,
31	};
32	use sha2::{Digest, Sha256};
33	use uuid::Uuid;
34	
35	use crate::adapters::store::JsonStore;
36	use crate::ports::remote::{
37	    DEVICES_FILE, IDENTITY_FILE, IDENTITY_SCHEMA_VERSION, Identity, Listen, PairedDevice,
38	    RemoteStore,
39	};
40	
41	// --- the files
42	
43	/// `identity.json` and `devices.json` in the data directory, written
44	/// the way every store file is: a temp file, fsync, rename.
45	pub struct RemoteFiles {
46	    dir: PathBuf,
47	}
48	
49	impl RemoteFiles {
50	    #[must_use]
51	    pub fn new(dir: PathBuf) -> Self {
52	        Self { dir }
53	    }
54	
55	    fn load<T: serde::de::DeserializeOwned>(&self, name: &str) -> Result<Option<T>, String> {
56	        let path = self.dir.join(name);
57	        match std::fs::read(&path) {
58	            Ok(bytes) => serde_json::from_slice(&bytes)
59	                .map(Some)
60	                .map_err(|e| format!("{}: {e}", path.display())),
61	            Err(e) if e.kind() == io::ErrorKind::NotFound => Ok(None),
62	            Err(e) => Err(format!("{}: {e}", path.display())),
63	        }
64	    }
65	
66	    fn save<T: serde::Serialize>(&self, name: &str, value: &T) -> Result<(), String> {
67	        let json = serde_json::to_vec_pretty(value).map_err(|e| e.to_string())?;
68	        JsonStore::write_atomic(&self.dir, &self.dir.join(name), &json, false)
69	            .map_err(|e| e.to_string())
70	    }
71	}
72	
73	impl RemoteStore for RemoteFiles {
74	    fn load_identity(&self) -> Result<Option<Identity>, String> {
75	        self.load(IDENTITY_FILE)
76	    }
77	    fn save_identity(&self, identity: &Identity) -> Result<(), String> {
78	        self.save(IDENTITY_FILE, identity)
79	    }
80	    fn load_devices(&self) -> Result<Vec<PairedDevice>, String> {
81	        Ok(self.load(DEVICES_FILE)?.unwrap_or_default())
82	    }
83	    fn save_devices(&self, devices: &[PairedDevice]) -> Result<(), String> {
84	        self.save(DEVICES_FILE, &devices)
85	    }
86	}
87	
88	// --- identity, certificate and key
89	
90	/// A fresh identity: a P-256 key and a self-signed certificate over it
91	/// that never expires in practice (rcgen's default `not_after` is the
92	/// year 4096). Returns the identity and the key as PEM, which goes to
93	/// the Keychain and nowhere else. `server_id` is kept when given: a
94	/// rotated key is a new identity for clients but the same installation.
95	pub fn make_identity(
96	    server_id: Option<Uuid>,
97	    server_name: &str,
98	    listen: Listen,
99	) -> Result<(Identity, String), String> {
100	    let server_id = server_id.unwrap_or_else(Uuid::new_v4);
101	    let key = rcgen::KeyPair::generate().map_err(|e| format!("key: {e}"))?;
102	    let mut params = rcgen::CertificateParams::new(Vec::<String>::new())
103	        .map_err(|e| format!("certificate: {e}"))?;
104	    params.distinguished_name.push(
105	        rcgen::DnType::CommonName,
106	        format!("Switchboard {server_id}"),
107	    );
108	    let cert = params
109	        .self_signed(&key)
110	        .map_err(|e| format!("certificate: {e}"))?;
111	    let der = cert.der().to_vec();
112	    let spki_sha256 = sha256_hex(&key.subject_public_key_info());
113	    debug_assert_eq!(
114	        spki_sha256_of_cert(&der).as_deref(),
115	        Some(spki_sha256.as_str())
116	    );
117	    let identity = Identity {
118	        schema_version: IDENTITY_SCHEMA_VERSION,
119	        server_id,
120	        server_name: server_name.to_owned(),
121	        certificate: base64::engine::general_purpose::STANDARD.encode(&der),
122	        spki_sha256,
123	        created: SystemTime::now(),
124	        listen,
125	    };
126	    Ok((identity, key.serialize_pem()))
127	}
128	
129	/// The certificate's DER back from the identity.
130	pub fn certificate_der(identity: &Identity) -> Result<Vec<u8>, String> {
131	    base64::engine::general_purpose::STANDARD
132	        .decode(&identity.certificate)
133	        .map_err(|e| format!("certificate: {e}"))
134	}
135	
136	/// The SPKI hash of a PEM key, to check that the key in the Keychain
137	/// is the one the identity's certificate was made over.
138	pub fn spki_sha256_of_key(pem: &str) -> Result<String, String> {
139	    let key = rcgen::KeyPair::from_pem(pem).map_err(|e| format!("key: {e}"))?;
140	    Ok(sha256_hex(&key.subject_public_key_info()))
141	}
142	
143	/// The server side of TLS: the identity's certificate over the key.
144	pub fn tls_config(identity: &Identity, key_pem: &str) -> Result<Arc<ServerConfig>, String> {
145	    let cert = CertificateDer::from(certificate_der(identity)?);
146	    let key = rcgen::KeyPair::from_pem(key_pem).map_err(|e| format!("key: {e}"))?;
147	    let key = PrivateKeyDer::Pkcs8(PrivatePkcs8KeyDer::from(key.serialize_der()));
148	    let config = ServerConfig::builder_with_provider(provider())
149	        .with_safe_default_protocol_versions()
150	        .map_err(|e| e.to_string())?
151	        .with_no_client_auth()
152	        .with_single_cert(vec![cert], key)
153	        .map_err(|e| e.to_string())?;
154	    Ok(Arc::new(config))
155	}
156	
157	/// The crypto provider every connection uses: `ring`, which the tree
158	/// already builds. Named explicitly so a second provider in the tree
159	/// can never make the default ambiguous.
160	fn provider() -> Arc<CryptoProvider> {
161	    Arc::new(rustls::crypto::ring::default_provider())
162	}
163	
164	/// A client that trusts exactly one public key, by the hash of its
165	/// `SubjectPublicKeyInfo`, and nothing else: no names, no dates, no
166	/// chain. What a paired device does on every connection; here for the
167	/// tests and for a Rust client.
168	pub fn pinned_client(spki_sha256: &str) -> Result<Arc<ClientConfig>, String> {
169	    let provider = provider();
170	    let config = ClientConfig::builder_with_provider(Arc::clone(&provider))
171	        .with_safe_default_protocol_versions()
172	        .map_err(|e| e.to_string())?
173	        .dangerous()
174	        .with_custom_certificate_verifier(Arc::new(Pin {
175	            spki_sha256: spki_sha256.to_owned(),
176	            provider,
177	        }))
178	        .with_no_client_auth();
179	    Ok(Arc::new(config))
180	}
181	
182	#[derive(Debug)]
183	struct Pin {
184	    spki_sha256: String,
185	    provider: Arc<CryptoProvider>,
186	}
187	
188	impl ServerCertVerifier for Pin {
189	    fn verify_server_cert(
190	        &self,
191	        end_entity: &CertificateDer<'_>,
192	        _intermediates: &[CertificateDer<'_>],
193	        _server_name: &ServerName<'_>,
194	        _ocsp_response: &[u8],
195	        _now: UnixTime,
196	    ) -> Result<ServerCertVerified, rustls::Error> {
197	        if spki_sha256_of_cert(end_entity).as_deref() == Some(self.spki_sha256.as_str()) {
198	            Ok(ServerCertVerified::assertion())
199	        } else {
200	            Err(rustls::Error::General(
201	                "the host's key is not the pinned one".into(),
202	            ))
203	        }
204	    }
205	
206	    fn verify_tls12_signature(
207	        &self,
208	        message: &[u8],
209	        cert: &CertificateDer<'_>,
210	        dss: &DigitallySignedStruct,
211	    ) -> Result<HandshakeSignatureValid, rustls::Error> {
212	        rustls::crypto::verify_tls12_signature(
213	            message,
214	            cert,
215	            dss,
216	            &self.provider.signature_verification_algorithms,
217	        )
218	    }
219	
220	    fn verify_tls13_signature(
221	        &self,
222	        message: &[u8],
223	        cert: &CertificateDer<'_>,
224	        dss: &DigitallySignedStruct,
225	    ) -> Result<HandshakeSignatureValid, rustls::Error> {
226	        rustls::crypto::verify_tls13_signature(
227	            message,
228	            cert,
229	            dss,
230	            &self.provider.signature_verification_algorithms,
231	        )
232	    }
233	
234	    fn supported_verify_schemes(&self) -> Vec<SignatureScheme> {
235	        self.provider
236	            .signature_verification_algorithms
237	            .supported_schemes()
238	    }
239	}
240	
241	/// SHA-256 of the certificate's `SubjectPublicKeyInfo`, hex. The
242	/// certificate is walked as DER: `Certificate { tbsCertificate {
243	/// [0] version, serialNumber, signature, issuer, validity, subject,
244	/// subjectPublicKeyInfo, .. }, .. }`, and the whole SPKI element is
245	/// hashed, which is what `rcgen::KeyPair::public_key_der` returns.
246	#[must_use]
247	pub fn spki_sha256_of_cert(der: &[u8]) -> Option<String> {
248	    let (0x30, tbs_and_rest, _) = der_element(der)? else {
249	        return None;
250	    };
251	    let (0x30, mut rest, _) = der_element(tbs_and_rest)? else {
252	        return None;
253	    };
254	    // The version is explicit and optional; rcgen writes it.
255	    if rest.first() == Some(&0xA0) {
256	        rest = der_element(rest)?.2;
257	    }
258	    for _ in 0..5 {
259	        rest = der_element(rest)?.2;
260	    }
261	    let (0x30, _, after) = der_element(rest)? else {
262	        return None;
263	    };
264	    Some(sha256_hex(&rest[..rest.len() - after.len()]))
265	}
266	
267	/// One DER element: its tag, its content, and what follows it.
268	fn der_element(bytes: &[u8]) -> Option<(u8, &[u8], &[u8])> {
269	    let (&tag, after_tag) = bytes.split_first()?;
270	    let (&first, after_first) = after_tag.split_first()?;
271	    let (length, content_at) = if first < 0x80 {
272	        (usize::from(first), after_first)
273	    } else {
274	        let count = usize::from(first & 0x7f);
275	        if count == 0 || count > 4 || after_first.len() < count {
276	            return None;
277	        }
278	        let length = after_first[..count]
279	            .iter()
280	            .fold(0usize, |n, &b| (n << 8) | usize::from(b));
281	        (length, &after_first[count..])
282	    };
283	    if content_at.len() < length {
284	        return None;
285	    }
286	    let (content, rest) = content_at.split_at(length);
287	    Some((tag, content, rest))
288	}
289	
290	/// Lowercase hex of SHA-256 over `bytes`.
291	#[must_use]
292	pub fn sha256_hex(bytes: &[u8]) -> String {
293	    Sha256::digest(bytes)
294	        .iter()
295	        .fold(String::with_capacity(64), |mut s, b| {
296	            let _ = write!(s, "{b:02x}");
297	            s
298	        })
299	}
300	
301	/// The name a new identity starts with: the machine's short host name,
302	/// or "Switchboard" when it has none.
303	#[must_use]
304	pub fn default_server_name() -> String {
305	    std::process::Command::new("hostname")
306	        .arg("-s")
307	        .output()
308	        .ok()
309	        .and_then(|o| String::from_utf8(o.stdout).ok())
310	        .map(|s| s.trim().to_owned())
311	        .filter(|s| !s.is_empty())
312	        .unwrap_or_else(|| "Switchboard".into())
313	}
314	
315	// --- random material
316	
317	/// The pairing code's alphabet: Crockford's base 32, with no I, L, O
318	/// or U, so a code read aloud or typed is never ambiguous.
319	pub const CODE_ALPHABET: &[u8; 32] = b"0123456789ABCDEFGHJKMNPQRSTVWXYZ";
320	/// Eight characters of five bits: 40 bits, single use, three tries.
321	pub const CODE_LENGTH: usize = 8;
322	
323	/// A fresh pairing code from the OS random source.
324	#[must_use]
325	pub fn pairing_code() -> String {
326	    let mut bytes = [0u8; CODE_LENGTH];
327	    fill_random(&mut bytes);
328	    bytes
329	        .iter()
330	        .map(|b| char::from(CODE_ALPHABET[usize::from(b % 32)]))
331	        .collect()
332	}
333	
334	/// A fresh bearer token: 32 random bytes as base64url without padding,
335	/// 43 characters. It is shown to the device once and never stored.
336	#[must_use]
337	pub fn bearer_token() -> String {
338	    let mut bytes = [0u8; 32];
339	    fill_random(&mut bytes);
340	    base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(bytes)
341	}
342	
343	/// What `devices.json` keeps of a token.
344	#[must_use]
345	pub fn token_sha256(token: &str) -> String {
346	    sha256_hex(token.as_bytes())
347	}
348	
349	fn fill_random(bytes: &mut [u8]) {
350	    // The OS random source failing is not something to carry on from.
351	    getrandom::fill(bytes).expect("the OS random source");
352	}
353	
354	// --- HTTP
355	
356	/// One request as it came off the socket, with what the frame needs
357	/// and nothing it does not: the bearer token is taken out of the
358	/// headers so it is never logged with them.
359	#[derive(Debug, Clone, PartialEq, Eq)]
360	pub struct RemoteRequest {
361	    pub method: String,
362	    /// The path without its query string.
363	    pub path: String,
364	    /// The query string's pairs, undecoded: ids and numbers only.
365	    pub query: Vec<(String, String)>,
366	    pub body: Vec<u8>,
367	    /// The `Authorization: Bearer` value, if any.
368	    pub bearer: Option<String>,
369	    /// The `Sec-WebSocket-Key` of a request that asks to upgrade to a
370	    /// WebSocket; the frame answers [`SUBSCRIBED`] to accept it.
371	    pub upgrade: Option<String>,
372	}
373	
374	impl RemoteRequest {
375	    /// The first value of a query parameter.
376	    #[must_use]
377	    pub fn param(&self, name: &str) -> Option<&str> {
378	        self.query
379	            .iter()
380	            .find(|(n, _)| n == name)
381	            .map(|(_, v)| v.as_str())
382	    }
383	}
384	
385	/// What the frame answers: a status and a JSON body, and whether the
386	/// request was made by a paired device, which moves the connection
387	/// from the unauthenticated pool to the paired one.
388	#[derive(Debug, Clone, PartialEq, Eq)]
389	pub struct RemoteReply {
390	    pub status: u16,
391	    pub body: Vec<u8>,
392	    pub authenticated: bool,
393	}
394	
395	/// One request off a connection, with the channel its reply goes back
396	/// on and, for an upgrade request, the queue the connection will feed
397	/// its WebSocket from once the frame accepts.
398	pub struct RemoteIncoming {
399	    pub request: RemoteRequest,
400	    pub reply: SyncSender<RemoteReply>,
401	    pub subscriber: Option<SubscriberQueue>,
402	}
403	
404	/// The status the frame answers an upgrade request with to accept it;
405	/// the connection thread then writes the 101 and becomes a subscriber.
406	pub const SUBSCRIBED: u16 = 101;
407	
408	/// How many events a subscriber may fall behind before it is dropped.
409	pub const SUBSCRIBER_QUEUE: usize = 256;
410	
411	/// How long a subscriber's thread waits for an event before it looks
412	/// for a frame from the device (a close, a ping, a `watch`).
413	const SUBSCRIBER_POLL: Duration = Duration::from_millis(50);
414	
415	/// The frame's end of a subscriber: events go in as JSON text; a full
416	/// queue drops the sender with `overflow` set, which the connection
417	/// thread turns into `resync_required` and a close. `id` names the
418	/// subscriber in the frames it sends back.
419	pub struct SubscriberQueue {
420	    pub id: u64,
421	    pub tx: SyncSender<String>,
422	    pub overflow: Arc<AtomicBool>,
423	}
424	
425	/// A text frame a subscribed device sent (`watch`, `unwatch`), or
426	/// `None` once its socket ended, however it ended.
427	pub struct SubscriberFrame {
428	    pub subscriber: u64,
429	    pub text: Option<String>,
430	}
431	
432	/// How many device frames may wait for the frame thread.
433	const FRAMES: usize = 64;
434	
435	/// The most a request line and its headers may take, and the most a
436	/// body may be.
437	pub const MAX_HEAD: usize = 8 * 1024;
438	pub const MAX_BODY: usize = 64 * 1024;
439	
440	/// The head of one HTTP/1.1 request: method, target, lowercased
441	/// headers, body. `None` at a clean end of stream before any byte; an
442	/// oversized or malformed request is an error that closes the
443	/// connection.
444	fn read_request<R: Read>(reader: &mut BufReader<R>) -> io::Result<Option<RemoteRequest>> {
445	    let mut line = String::new();
446	    if reader.read_line(&mut line)? == 0 {
447	        return Ok(None);
448	    }
449	    let mut parts = line.split_whitespace();
450	    let (Some(method), Some(target)) = (parts.next(), parts.next()) else {
451	        return Err(io::Error::new(
452	            io::ErrorKind::InvalidData,
453	            "bad request line",
454	        ));
455	    };
456	    let mut headers: Vec<(String, String)> = Vec::new();
457	    let mut total = line.len();
458	    loop {
459	        let mut h = String::new();
460	        if reader.read_line(&mut h)? == 0 {
461	            return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "headers cut"));
462	        }
463	        total += h.len();
464	        if total > MAX_HEAD {
465	            return Err(io::Error::new(io::ErrorKind::InvalidData, "head too large"));
466	        }
467	        let h = h.trim_end();
468	        if h.is_empty() {
469	            break;
470	        }
471	        if let Some((n, v)) = h.split_once(':') {
472	            headers.push((n.trim().to_ascii_lowercase(), v.trim().to_owned()));
473	        }
474	    }
475	    let header = |name: &str| {
476	        headers
477	            .iter()
478	            .find(|(n, _)| n == name)
479	            .map(|(_, v)| v.as_str())
480	    };
481	    let length: usize = header("content-length")
482	        .and_then(|v| v.parse().ok())
483	        .unwrap_or(0);
484	    if length > MAX_BODY {
485	        return Err(io::Error::new(io::ErrorKind::InvalidData, "body too large"));
486	    }
487	    let bearer = header("authorization")
488	        .and_then(|v| v.strip_prefix("Bearer "))
489	        .map(|t| t.trim().to_owned())
490	        .filter(|t| !t.is_empty());
491	    let upgrade = header("upgrade")
492	        .filter(|u| u.eq_ignore_ascii_case("websocket"))
493	        .and_then(|_| header("sec-websocket-key"))
494	        .map(str::to_owned);
495	    let (path, query) = target.split_once('?').unwrap_or((target, ""));
496	    let query = query
497	        .split('&')
498	        .filter(|s| !s.is_empty())
499	        .map(|pair| {
500	            let (n, v) = pair.split_once('=').unwrap_or((pair, ""));
501	            (n.to_owned(), v.to_owned())
502	        })
503	        .collect();
504	    let mut body = vec![0; length];
505	    reader.read_exact(&mut body)?;
506	    Ok(Some(RemoteRequest {
507	        method: method.to_owned(),
508	        path: path.to_owned(),
509	        query,
510	        body,
511	        bearer,
512	        upgrade,
513	    }))
514	}
