186	                    format!("Key {}", short_hash(&identity.spki_sha256)),
187	                ));
188	                if !address.is_empty() {
189	                    ui.label(theme::meta_text(ui, format!("Address {address}")));
190	                }
191	                ui.label(theme::meta_text(
192	                    ui,
193	                    format!(
194	                        "Scan, or type the key and the code. Grants {} scope. Open for five minutes or three wrong codes.",
195	                        window.scope.word()
196	                    ),
197	                ));
198	                ui.horizontal(|ui| {
199	                    // The QR's text, for a client without a camera (the
200	                    // command-line browser takes it as one argument).
201	                    if theme::secondary(ui, "Copy invite")
202	                        .on_hover_text("The QR code's text, to paste into a client")
203	                        .clicked()
204	                    {
