768	/// One connection: the handshake, then a request and a reply at a time
769	/// until the device hangs up or a deadline passes.
770	fn connection(tcp: TcpStream, shared: &Arc<Shared>, paired: &AtomicBool) -> io::Result<()> {
771	    tcp.set_read_timeout(Some(HANDSHAKE_TIMEOUT))?;
772	    tcp.set_write_timeout(Some(WRITE_TIMEOUT))?;
773	    // A reply is one record and goes out at once; Nagle with the
774	    // device's delayed ACK would otherwise add milliseconds per request.
775	    tcp.set_nodelay(true)?;
776	    let conn = ServerConnection::new(Arc::clone(&shared.tls)).map_err(io::Error::other)?;
777	    let mut stream = StreamOwned::new(conn, tcp);
778	    while stream.conn.is_handshaking() {
779	        stream.conn.complete_io(&mut stream.sock)?;
780	    }
781	    let mut reader = BufReader::new(stream);
782	    let mut first = true;
783	    while let Some(request) = read_request(&mut reader)? {
784	        if first {
785	            reader.get_ref().sock.set_read_timeout(Some(IDLE_TIMEOUT))?;
786	            first = false;
787	        }
788	        if shared.limits.limited(&request.path) {
789	            respond(
790	                reader.get_mut(),
791	                429,
792	                &error_body("rate_limited", "too many requests; try again in a minute"),
793	            )?;
794	            continue;
795	        }
796	        let (reply_tx, reply_rx) = mpsc::sync_channel(1);
797	        let upgrade_key = request.upgrade.clone();
798	        let mut queue = None;
799	        let queue_for_frame = upgrade_key.as_ref().map(|_| {
800	            let (q_tx, q_rx) = mpsc::sync_channel::<String>(SUBSCRIBER_QUEUE);
801	            let overflow = Arc::new(AtomicBool::new(false));
802	            let id = shared.next_subscriber.fetch_add(1, Ordering::SeqCst);
803	            queue = Some((id, q_rx, Arc::clone(&overflow)));
804	            SubscriberQueue {
805	                id,
806	                tx: q_tx,
807	                overflow,
808	            }
809	        });
810	        if shared
811	            .requests
812	            .try_send(RemoteIncoming {
813	                request,
814	                reply: reply_tx,
815	                subscriber: queue_for_frame,
816	            })
817	            .is_err()
818	        {
819	            respond(
820	                reader.get_mut(),
821	                503,
822	                &error_body("busy", "the host is busy; try again"),
823	            )?;
824	            continue;
825	        }
826	        (shared.wake)();
827	        let reply = match reply_rx.recv_timeout(ANSWER_TIMEOUT) {
828	            Ok(reply) => reply,
829	            Err(_) => RemoteReply {
830	                status: 504,
831	                body: error_body("no_answer", "the app did not answer in time"),
832	                authenticated: false,
833	            },
834	        };
835	        if reply.authenticated && !paired.load(Ordering::SeqCst) {
836	            // The device moves from the unauthenticated pool to the
837	            // paired one on its first authenticated request.
838	            if shared.pools.paired.load(Ordering::SeqCst) >= MAX_PAIRED {
839	                respond(
840	                    reader.get_mut(),
841	                    503,
842	                    &error_body("full", "too many paired connections"),
843	                )?;
844	                return Ok(());
845	            }
846	            shared.pools.paired.fetch_add(1, Ordering::SeqCst);
847	            shared.pools.unauthenticated.fetch_sub(1, Ordering::SeqCst);
848	            paired.store(true, Ordering::SeqCst);
849	        }
850	        if reply.status == SUBSCRIBED
851	            && let (Some(key), Some((id, q_rx, overflow))) = (upgrade_key, queue)
852	        {
853	            respond_upgrade(reader.get_mut(), &key)?;
854	            let out = subscriber(reader.into_inner(), &q_rx, &overflow, id, shared);
855	            let ended = SubscriberFrame {
856	                subscriber: id,
857	                text: None,
858	            };
859	            if shared.frames.send(ended).is_ok() {
860	                (shared.wake)();
861	            }
862	            return out;
863	        }
864	        respond(reader.get_mut(), reply.status, &reply.body)?;
865	    }
866	    Ok(())
867	}
868	
869	/// Feed one WebSocket from its queue until the frame drops the queue
870	/// (a revocation, or an overflow, which ends with `resync_required`)
871	/// or the device closes. The socket is non-blocking: an event goes out
872	/// the moment it is queued, the device's own frames are looked for
873	/// only when there is nothing to send (a close ends the subscription,
874	/// a ping is answered by the library, a text frame goes to the frame
875	/// thread as a `SubscriberFrame`), and a device that stops reading
876	/// stalls only this thread, for `WRITE_TIMEOUT` at most, while the
877	/// frame fills and then drops its queue.
878	fn subscriber(
879	    stream: StreamOwned<ServerConnection, TcpStream>,
880	    events: &Receiver<String>,
881	    overflow: &AtomicBool,
882	    id: u64,
883	    shared: &Shared,
884	) -> io::Result<()> {
885	    stream.sock.set_nonblocking(true)?;
886	    let mut ws =
887	        tungstenite::WebSocket::from_raw_socket(stream, tungstenite::protocol::Role::Server, None);
888	    loop {
889	        match events.recv_timeout(SUBSCRIBER_POLL) {
890	            Ok(text) => {
891	                send_text(&mut ws, text)?;
892	                continue;
893	            }
894	            Err(mpsc::RecvTimeoutError::Timeout) => {}
895	            Err(mpsc::RecvTimeoutError::Disconnected) => {
896	                if overflow.load(Ordering::SeqCst) {
897	                    let _ = send_text(&mut ws, "{\"type\":\"resync_required\"}".into());
898	                }
899	                let _ = ws.close(None);
900	                let _ = flush_by(&mut ws, Instant::now() + WRITE_TIMEOUT);
901	                return Ok(());
902	            }
903	        }
904	        match ws.read() {
905	            Ok(tungstenite::Message::Close(_)) => return Ok(()),
906	            Ok(tungstenite::Message::Text(text)) => {
907	                let frame = SubscriberFrame {
908	                    subscriber: id,
909	                    text: Some(text.to_string()),
910	                };
911	                if shared.frames.try_send(frame).is_ok() {
912	                    (shared.wake)();
913	                }
914	            }
915	            Ok(_) => {}
916	            Err(tungstenite::Error::Io(e)) if e.kind() == io::ErrorKind::WouldBlock => {}
917	            Err(tungstenite::Error::ConnectionClosed | tungstenite::Error::AlreadyClosed) => {
918	                return Ok(());
919	            }
920	            Err(e) => return Err(io::Error::other(e.to_string())),
921	        }
922	    }
923	}
924	
925	type Socket = tungstenite::WebSocket<StreamOwned<ServerConnection, TcpStream>>;
926	
927	/// Queue one text frame and write it out, waiting up to `WRITE_TIMEOUT`
928	/// for a full socket to drain.
929	fn send_text(ws: &mut Socket, text: String) -> io::Result<()> {
930	    match ws.write(tungstenite::Message::Text(text.into())) {
931	        Ok(()) => {}
932	        Err(tungstenite::Error::Io(e)) if e.kind() == io::ErrorKind::WouldBlock => {}
933	        Err(e) => return Err(io::Error::other(e.to_string())),
934	    }
935	    flush_by(ws, Instant::now() + WRITE_TIMEOUT)
936	}
937	
938	/// Flush what is queued, retrying a full socket until `deadline`.
939	fn flush_by(ws: &mut Socket, deadline: Instant) -> io::Result<()> {
940	    loop {
941	        match ws.flush() {
942	            Ok(()) => return Ok(()),
943	            Err(tungstenite::Error::Io(e)) if e.kind() == io::ErrorKind::WouldBlock => {
944	                if Instant::now() >= deadline {
945	                    return Err(io::Error::new(
946	                        io::ErrorKind::TimedOut,
947	                        "the device stopped reading",
948	                    ));
949	                }
950	                std::thread::sleep(Duration::from_millis(5));
951	            }
952	            Err(e) => return Err(io::Error::other(e.to_string())),
953	        }
954	    }
955	}
