1	//! The remote port's state: the host's identity, the devices paired
2	//! with it, and the pairing window. Random material (the code, a
3	//! token) is made outside and arrives in the action; here it is only
4	//! compared and kept, so every transition is a plain function of its
5	//! inputs.
6	
7	use std::time::SystemTime;
8	
9	use uuid::Uuid;
10	
11	use super::action::PairingWindow;
12	use super::action::{AppAction, AppCore, Clock, Effect, Out, PAIRING_ATTEMPTS, PAIRING_WINDOW};
13	use crate::ports::remote::{Identity, PairedDevice, Scope};
14	
15	/// A device's last-seen time is saved when it moved by at least this
16	/// much, so a polling device does not rewrite `devices.json` on every
17	/// request.
18	const LAST_SEEN_SAVE_INTERVAL_SECS: u64 = 300;
19	
20	impl AppCore {
21	    pub(super) fn remote_action(&mut self, action: AppAction, now: Clock, out: &mut Out) {
22	        match action {
23	            AppAction::IdentityLoaded {
24	                identity,
25	                devices,
26	                rotated,
27	            } => {
28	                self.identity = Some(identity);
29	                self.devices = devices;
30	                self.identity_rotated_at = rotated.then_some(now.mono);
31	            }
32	            AppAction::SetServerName(name) => {
33	                let name = name.trim().to_owned();
34	                if !name.is_empty() {
35	                    self.update_identity(out, |i| i.server_name = name);
36	                }
37	            }
38	            AppAction::SetRemoteListen { lan, port } => {
39	                if port != 0 {
40	                    self.update_identity(out, |i| {
41	                        i.listen.lan = lan;
42	                        i.listen.port = port;
43	                    });
44	                }
45	            }
46	            AppAction::OpenPairing { code, scope } => {
47	                // Typed by hand on the device, so case never matters.
48	                self.pairing = Some(PairingWindow {
49	                    until: now.mono + PAIRING_WINDOW,
50	                    code: code.trim().to_ascii_uppercase(),
51	                    scope,
52	                    failures: 0,
53	                });
54	            }
55	            AppAction::ClosePairing => self.pairing = None,
56	            AppAction::PairingFailed => {
57	                if let Some(p) = &mut self.pairing {
58	                    p.failures += 1;
59	                    if p.failures >= PAIRING_ATTEMPTS {
60	                        self.pairing = None;
61	                        self.error("Pairing closed: three attempts failed.");
62	                    }
63	                }
64	            }
65	            AppAction::Paired(device) => {
66	                // The code is single-use: the window closes with the
67	                // first pairing made through it.
68	                self.pairing = None;
69	                self.devices.push(device);
70	                self.save_devices(out);
71	            }
72	            AppAction::DeviceSeen(id) => {
73	                let Some(device) = self.devices.iter_mut().find(|d| d.id == id) else {
74	                    return;
75	                };
76	                let stale = device.last_seen.is_none_or(|seen| {
77	                    now.wall
78	                        .duration_since(seen)
79	                        .is_ok_and(|d| d.as_secs() >= LAST_SEEN_SAVE_INTERVAL_SECS)
80	                });
81	                device.last_seen = Some(now.wall);
82	                if stale {
83	                    self.save_devices(out);
84	                }
85	            }
86	            AppAction::RevokeDevice(id) => {
87	                let before = self.devices.len();
88	                self.devices.retain(|d| d.id != id);
89	                if self.devices.len() != before {
90	                    self.save_devices(out);
91	                }
92	            }
93	            AppAction::SetDeviceScope { device, scope } => {
94	                if let Some(d) = self.devices.iter_mut().find(|d| d.id == device)
95	                    && d.scope != scope
96	                {
97	                    d.scope = scope;
98	                    self.save_devices(out);
99	                }
100	            }
101	            _ => unreachable!("dispatched by `dispatch` itself"),
102	        }
103	    }
104	
105	    fn update_identity(&mut self, out: &mut Out, change: impl FnOnce(&mut Identity)) {
106	        let Some(identity) = &self.identity else {
107	            return;
108	        };
109	        let mut next = identity.clone();
110	        change(&mut next);
111	        if Some(&next) != self.identity.as_ref() {
112	            self.identity = Some(next.clone());
113	            if !self.read_only {
114	                out.push(Effect::SaveIdentity(next));
115	            }
116	        }
117	    }
118	
119	    fn save_devices(&self, out: &mut Out) {
120	        if !self.read_only {
121	            out.push(Effect::SaveDevices(self.devices.clone()));
122	        }
123	    }
124	
125	    /// The host's identity, once loaded.
126	    #[must_use]
127	    pub fn identity(&self) -> Option<&Identity> {
128	        self.identity.as_ref()
129	    }
130	
131	    /// The key was remade at this launch: every earlier pairing is gone.
132	    #[must_use]
133	    pub fn identity_rotated(&self) -> bool {
134	        self.identity_rotated_at.is_some()
135	    }
136	
137	    /// The devices paired with this host.
138	    #[must_use]
139	    pub fn devices(&self) -> &[PairedDevice] {
140	        &self.devices
141	    }
142	
143	    /// The device holding the token with this hash.
144	    #[must_use]
145	    pub fn device_by_token(&self, token_sha256: &str) -> Option<&PairedDevice> {
146	        self.devices.iter().find(|d| d.token_sha256 == token_sha256)
147	    }
148	
149	    /// The pairing window, while it is open at `now`. `Tick` clears a
150	    /// passed one; between ticks this checks the time itself.
151	    #[must_use]
152	    pub fn pairing_at(&self, now: Clock) -> Option<&PairingWindow> {
153	        self.pairing.as_ref().filter(|p| p.until > now.mono)
154	    }
155	
156	    /// The pairing window as last set, passed or not; the dialog uses
157	    /// `pairing_at` and this is for tests.
158	    #[must_use]
159	    pub fn pairing(&self) -> Option<&PairingWindow> {
160	        self.pairing.as_ref()
161	    }
162	
163	    /// A device record for a pairing that matched: the window's scope,
164	    /// the token's hash, and the time.
165	    #[must_use]
166	    pub fn new_device(&self, name: &str, token_sha256: String, at: SystemTime) -> PairedDevice {
167	        PairedDevice {
168	            id: Uuid::new_v4(),
169	            name: name.trim().chars().take(64).collect(),
170	            scope: self.pairing.as_ref().map_or(Scope::Read, |p| p.scope),
171	            token_sha256,
172	            created: at,
173	            last_seen: None,
174	        }
175	    }
176	}
