3014	    /// One HTTP request from a device, answered on the frame: `/info`
3015	    /// and `/pair` to anyone, the allowlisted reads to a paired device,
3016	    /// everything else refused before it is translated to the wire.
3017	    fn serve_remote(
3018	        &mut self,
3019	        request: &RemoteRequest,
3020	        subscriber: Option<SubscriberQueue>,
3021	        reply: &mpsc::SyncSender<RemoteReply>,
3022	    ) -> Served {
3023	        let Some(rest) = request.path.strip_prefix("/api/v1/") else {
3024	            return Served::Now(self.refuse(request, 404, "not_found", "no such endpoint", false));
3025	        };
3026	        let segments: Vec<&str> = rest.split('/').collect();
3027	        match (request.method.as_str(), segments.as_slice()) {
3028	            ("GET", ["info"]) => return Served::Now(self.remote_info()),
3029	            ("POST", ["pair"]) => return Served::Now(self.remote_pair(request)),
3030	            _ => {}
3031	        }
3032	        let device = match self.authenticate(request) {
3033	            Ok(device) => device,
3034	            Err(refused) => return Served::Now(refused),
3035	        };
3036	        if let ("GET", ["events"]) = (request.method.as_str(), segments.as_slice()) {
3037	            return Served::Now(self.remote_subscribe(request, device.id, subscriber));
3038	        }
3039	        let notes_cap = if matches!(segments.as_slice(), ["sessions", _]) {
3040	            NOTES_CAP_ALONE
3041	        } else {
3042	            STRING_CAP
3043	        };
3044	        let body = match (request.method.as_str(), segments.as_slice()) {
3045	            ("GET", ["projects"]) => wire::Body::Projects {
3046	                space: request.param("space").map(str::to_owned),
3047	            },
3048	            ("GET", ["spaces"]) => wire::Body::Spaces,
3049	            ("GET", ["spaces", space, "sets"]) => wire::Body::Sets {
3050	                space: (*space).to_owned(),
3051	            },
3052	            ("GET", ["sets", set]) => return Served::Now(self.remote_set(request, set)),
3053	            ("GET", ["projects", project, "sessions"]) => wire::Body::Sessions {
3054	                project: (*project).to_owned(),
3055	            },
3056	            ("GET", ["sessions", session]) => wire::Body::Session {
3057	                session: (*session).to_owned(),
3058	            },
3059	            ("GET", ["waiting"]) => wire::Body::Waiting,
3060	            ("GET", ["ops", op]) => wire::Body::OpStatus {
3061	                operation: (*op).to_owned(),
3062	            },
3063	            ("GET", ["sessions", session, "runs"]) => {
3064	                return Served::Now(self.remote_runs(request, session));
3065	            }
3066	            ("POST", ["sessions", session, verb @ ("send" | "resume" | "trust")]) => {
3067	                return Served::Now(self.remote_command(request, &device, session, verb));
3068	            }
3069	            ("POST", ["projects", project, "sessions"]) => {
3070	                return Served::Now(self.remote_new_session(request, &device, project));
3071	            }
3072	            ("GET" | "POST", ["sessions", session, "draft"]) => {
3073	                return Served::Now(self.remote_draft(request, &device, session));
3074	            }
3075	            ("POST", ["sessions", session, "dictation"]) => {
3076	                return Served::Now(self.remote_dictation(request, &device, session));
3077	            }
3078	            ("GET", ["dispatch", "tickets"]) => return Served::Now(self.remote_tickets(request)),
3079	            ("GET", ["dispatch", "tickets", ticket]) => {
3080	                return Served::Now(self.remote_ticket(request, ticket));
3081	            }
3082	            (
3083	                "POST",
3084	                [
3085	                    "dispatch",
3086	                    "tickets",
3087	                    ticket,
3088	                    verb @ ("decide" | "resume" | "close"),
3089	                ],
3090	            ) => {
3091	                return self.remote_ticket_command(request, &device, ticket, verb, reply);
3092	            }
3093	            ("GET", ["dispatch", "tickets", ticket, "events"]) => {
3094	                return self.remote_ticket_events(request, ticket, reply);
3095	            }
3096	            ("GET", ["dispatch", "tickets", ticket, "files", key]) => {
3097	                return self.remote_ticket_file(request, ticket, key, reply);
3098	            }
3099	            (
3100	                "GET",
3101	                ["sessions", _, "screen" | "conversation" | "last-response"]
3102	                | ["sessions", _, "conversation", _]
3103	                | ["sessions", _, "runs", _, "output"]
3104	                | ["projects", _, "files", _, ..],
3105	            ) => {
3106	                return self.remote_content_route(request, &segments, reply);
3107	            }
3108	            _ => {
3109	                return Served::Now(self.refuse(
3110	                    request,
3111	                    404,
3112	                    "not_found",
3113	                    "not available on this port",
3114	                    true,
3115	                ));
3116	            }
3117	        };
3118	        let mut reply = self.answer(&body);
3119	        if request.param("scope") != Some("all") {
3120	            Self::hide_workers(&mut reply);
3121	        }
3122	        Served::Now(self.remote_reply(request, &reply, notes_cap))
3123	    }
