3154	    /// A command under `control` scope. The body's `op` is the operation
3155	    /// id the device made, which is the idempotency key: the command
3156	    /// goes through `serve` as the control socket's do, so a send or a
3157	    /// resume is logged before it runs and a repeat of the op is
3158	    /// answered from the log without running again (§4.5).
3159	    fn remote_command(
3160	        &mut self,
3161	        request: &RemoteRequest,
3162	        device: &PairedDevice,
3163	        session: &str,
3164	        verb: &str,
3165	    ) -> RemoteReply {
3166	        if device.scope != Scope::Control {
3167	            return self.refuse(
3168	                request,
3169	                403,
3170	                "scope",
3171	                "this device reads only; raise its scope on the host",
3172	                true,
3173	            );
3174	        }
3175	        let Ok(body) = serde_json::from_slice::<serde_json::Value>(&request.body) else {
3176	            return self.refuse(request, 400, "bad_request", "the body is not JSON", true);
3177	        };
3178	        let field = |name: &str| body.get(name).and_then(|v| v.as_str()).map(str::trim);
3179	        let op = field("op").unwrap_or_default();
3180	        if op.is_empty() || op.len() > OP_CAP {
3181	            return self.refuse(
3182	                request,
3183	                400,
3184	                "bad_request",
3185	                "op is the operation id, 1 to 64 characters",
3186	                true,
3187	            );
3188	        }
3189	        let session = session.to_owned();
3190	        let body = match verb {
3191	            "send" => {
3192	                let text = field("text").unwrap_or_default();
3193	                if text.is_empty() || text.len() > SEND_BYTES_CAP {
3194	                    return self.refuse(
3195	                        request,
3196	                        400,
3197	                        "bad_request",
3198	                        "text is the message, 1 byte to 16 KiB",
3199	                        true,
3200	                    );
3201	                }
3202	                wire::Body::SessionSend {
3203	                    session,
3204	                    text: text.to_owned(),
3205	                }
3206	            }
3207	            "resume" => wire::Body::SessionResume { session },
3208	            _ => wire::Body::SessionTrust { session },
3209	        };
3210	        let reply = self.serve(&wire::Request::new(op, body));
3211	        if let wire::Reply::Failed { reason } = &reply
3212	            && reason.starts_with("interrupted")
3213	        {
3214	            return self.refuse(request, 409, "interrupted", reason, true);
3215	        }
3216	        self.remote_reply(request, &reply, STRING_CAP)
3217	    }
