3219	    /// A new session in a project under `control` scope, through
3220	    /// `session.new` as the CLI and Dispatch make theirs, the body's
3221	    /// `op` the key as for `remote_command`. A device opens an agent or
3222	    /// a shell, named, in the project's root or a directory under it,
3223	    /// never elsewhere on the disk; an agent's `prompt` becomes its
3224	    /// first turn, so the session is already working when its window
3225	    /// opens.
3226	    fn remote_new_session(
3227	        &mut self,
3228	        request: &RemoteRequest,
3229	        device: &PairedDevice,
3230	        project: &str,
3231	    ) -> RemoteReply {
3232	        if device.scope != Scope::Control {
3233	            return self.refuse(
3234	                request,
3235	                403,
3236	                "scope",
3237	                "this device reads only; raise its scope on the host",
3238	                true,
3239	            );
3240	        }
3241	        let Ok(body) = serde_json::from_slice::<serde_json::Value>(&request.body) else {
3242	            return self.refuse(request, 400, "bad_request", "the body is not JSON", true);
3243	        };
3244	        let field = |name: &str| body.get(name).and_then(|v| v.as_str()).map(str::trim);
3245	        let op = field("op").unwrap_or_default();
3246	        if op.is_empty() || op.len() > OP_CAP {
3247	            return self.refuse(
3248	                request,
3249	                400,
3250	                "bad_request",
3251	                "op is the operation id, 1 to 64 characters",
3252	                true,
3253	            );
3254	        }
3255	        let root = parse_uuid("project", project)
3256	            .ok()
3257	            .and_then(|id| self.core.workspace(ProjectId(id)))
3258	            .map(|w| w.project.root.clone());
3259	        let Some(root) = root else {
3260	            return self.refuse(request, 404, "not_found", "no such project", true);
3261	        };
3262	        let name = field("name").unwrap_or_default();
3263	        if name.is_empty() || name.len() > NAME_CAP {
3264	            return self.refuse(
3265	                request,
3266	                400,
3267	                "bad_request",
3268	                "name is the session's name, 1 to 128 bytes",
3269	                true,
3270	            );
3271	        }
3272	        let session_kind = match field("kind") {
3273	            Some("claude") => wire::SessionKind::Claude,
3274	            Some("codex") => wire::SessionKind::Codex,
3275	            Some("shell") => wire::SessionKind::Shell,
3276	            _ => {
3277	                return self.refuse(
3278	                    request,
3279	                    400,
3280	                    "bad_request",
3281	                    "kind is claude, codex or shell",
3282	                    true,
3283	                );
3284	            }
3285	        };
3286	        let cwd = match field("cwd").filter(|c| !c.is_empty()) {
3287	            None => root,
3288	            Some(text) => match project_dir(&root, text) {
3289	                Some(dir) => dir,
3290	                None => {
3291	                    return self.refuse(
3292	                        request,
3293	                        400,
3294	                        "bad_request",
3295	                        "cwd is a directory of the project, by a path under its root",
3296	                        true,
3297	                    );
3298	                }
3299	            },
3300	        };
3301	        let prompt = field("prompt").filter(|p| !p.is_empty()).map(str::to_owned);
3302	        if prompt.as_ref().is_some_and(|p| p.len() > SEND_BYTES_CAP) {
3303	            return self.refuse(
3304	                request,
3305	                400,
3306	                "bad_request",
3307	                "prompt is the first message, up to 16 KiB",
3308	                true,
3309	            );
3310	        }
3311	        let body = wire::Body::SessionNew {
3312	            project: project.to_owned(),
3313	            name: name.to_owned(),
3314	            session_kind,
3315	            cwd,
3316	            launch: wire::Launch::Shell,
3317	            prompt,
3318	            notes: String::new(),
3319	            env: std::collections::BTreeMap::new(),
3320	            env_sets: Vec::new(),
3321	            replaces: None,
3322	        };
3323	        let reply = self.serve(&wire::Request::new(op, body));
3324	        if let wire::Reply::Failed { reason } = &reply
3325	            && reason.starts_with("interrupted")
3326	        {
3327	            return self.refuse(request, 409, "interrupted", reason, true);
3328	        }
3329	        self.remote_reply(request, &reply, STRING_CAP)
3330	    }
