3357	    /// The draft as the device reads it, from the session's editor,
3358	    /// made now if the session has not been opened on the host.
3359	    fn draft_reply(&mut self, record: &SessionRecord) -> RemoteReply {
3360	        let editor =
3361	            prompt_box::ensure_editor(&self.core, &self.services, &mut self.ui_state, record);
3362	        let draft = serde_json::to_value(prompt_box::draft_view(editor)).unwrap_or_default();
