3366	    /// A session's prompt, its Prompt Box editor on the host (§4.5):
3367	    /// read by any paired device, and under the control scope edited
3368	    /// with the editor's own tools. `send` takes the draft's text to
3369	    /// the pane through `serve` with the device's op as the key, as
3370	    /// the plain send does, and clears the editor when it went.
3371	    fn remote_draft(
3372	        &mut self,
3373	        request: &RemoteRequest,
3374	        device: &PairedDevice,
3375	        session: &str,
3376	    ) -> RemoteReply {
3377	        let record = match self.draft_record(request, session) {
3378	            Ok(record) => record,
3379	            Err(reply) => return reply,
3380	        };
3381	        if request.method == "GET" {
3382	            return self.draft_reply(&record);
3383	        }
3384	        if device.scope != Scope::Control {
3385	            return self.refuse(
3386	                request,
3387	                403,
3388	                "scope",
3389	                "this device reads only; raise its scope on the host",
3390	                true,
3391	            );
3392	        }
3393	        let Ok(body) = serde_json::from_slice::<serde_json::Value>(&request.body) else {
3394	            return self.refuse(request, 400, "bad_request", "the body is not JSON", true);
3395	        };
3396	        let field = |name: &str| body.get(name).and_then(|v| v.as_str());
3397	        let action = field("action").unwrap_or_default();
3398	        let text = field("text");
3399	        if text.is_some_and(|t| t.len() > SEND_BYTES_CAP) {
3400	            return self.refuse(request, 400, "bad_request", "text is at most 16 KiB", true);
3401	        }
3402	        if action == "send" {
3403	            let op = field("op").map(str::trim).unwrap_or_default();
3404	            if op.is_empty() || op.len() > OP_CAP {
3405	                return self.refuse(
3406	                    request,
3407	                    400,
3408	                    "bad_request",
3409	                    "op is the operation id, 1 to 64 characters",
3410	                    true,
3411	                );
3412	            }
3413	            let editor =
3414	                prompt_box::ensure_editor(&self.core, &self.services, &mut self.ui_state, &record);
3415	            let text = prompt_box::draft_view(editor).text.trim().to_owned();
3416	            if text.is_empty() {
3417	                // A repeat of a send that went: the draft was cleared
3418	                // by it, and the op's log line is the answer.
3419	                let status = self.answer(&wire::Body::OpStatus {
3420	                    operation: op.to_owned(),
3421	                });
3422	                if let wire::Reply::OpStatus {
3423	                    status: wire::OpStatus::Done { reply },
3424	                } = status
3425	                {
3426	                    return self.remote_reply(request, &reply, STRING_CAP);
3427	                }
3428	                return self.refuse(request, 400, "failed", "the draft is empty", true);
3429	            }
3430	            let reply = self.serve(&wire::Request::new(
3431	                op,
3432	                wire::Body::SessionSend {
3433	                    session: session.to_owned(),
3434	                    text,
3435	                },
3436	            ));
3437	            match &reply {
3438	                wire::Reply::Failed { reason } if reason.starts_with("interrupted") => {
3439	                    return self.refuse(request, 409, "interrupted", reason, true);
3440	                }
3441	                wire::Reply::Failed { .. } => {
3442	                    return self.remote_reply(request, &reply, STRING_CAP);
3443	                }
3444	                _ => {}
3445	            }
3446	            let editor =
3447	                prompt_box::ensure_editor(&self.core, &self.services, &mut self.ui_state, &record);
3448	            editor.dispatch(promptbox::core::AppAction::ClearPrompt);
