336	/// One call on the control socket, for making records.
337	fn control(port: &mut Port, request: Request) -> Reply {
338	    let path = port.control.clone();
339	    let client = std::thread::spawn(move || {
340	        let mut client = Client::connect(&path).expect("connect");
341	        client.call(&request).expect("reply")
342	    });
343	    let deadline = std::time::Instant::now() + Duration::from_secs(5);
344	    while !client.is_finished() {
345	        assert!(std::time::Instant::now() < deadline, "no reply");
346	        port.app.serve_pending();
347	        std::thread::sleep(Duration::from_millis(2));
348	    }
349	    client.join().unwrap()
350	}
351	
352	fn made_id(reply: &Reply, kind: RecordKind) -> String {
353	    reply
354	        .made()
355	        .iter()
356	        .find(|m: &&Made| m.kind == kind)
357	        .unwrap_or_else(|| panic!("no {kind:?} in {reply:?}"))
358	        .id
359	        .clone()
360	}
