362	/// A space, a project in it, and a session in that, with `notes`.
363	fn seed(port: &mut Port, notes: &str) -> (String, String, String) {
364	    let reply = control(
365	        port,
366	        Request::new("sp", Body::SpaceNew { name: "D".into() }),
367	    );
368	    let space = made_id(&reply, RecordKind::Space);
369	    let reply = control(
370	        port,
371	        Request::new(
372	            "pj",
373	            Body::ProjectAdd {
374	                space: space.clone(),
375	                name: "#1".into(),
376	                root: PathBuf::from("/tmp"),
377	            },
378	        ),
379	    );
380	    let project = made_id(&reply, RecordKind::Project);
381	    let reply = control(
382	        port,
383	        Request::new(
384	            "se",
385	            Body::SessionNew {
386	                project: project.clone(),
387	                name: "investigator".into(),
388	                session_kind: SessionKind::Claude,
389	                cwd: PathBuf::from("/tmp"),
390	                launch: Launch::Shell,
391	                prompt: None,
392	                notes: notes.into(),
393	                env: std::collections::BTreeMap::new(),
394	                env_sets: Vec::new(),
395	                replaces: None,
396	            },
397	        ),
398	    );
399	    let session = made_id(&reply, RecordKind::Session);
400	    // The host lists no pane for it: a session that is not running.
401	    port.app.poll_now();
402	    (space, project, session)
403	}
404	
405	/// Open the pairing window with `code` and pair as `name`: the token.
406	fn pair(port: &mut Port, code: &str, scope: Scope, name: &str) -> String {
407	    port.app.dispatch(AppAction::OpenPairing {
408	        code: code.into(),
409	        scope,
410	    });
411	    let spki = port
412	        .remote
413	        .state()
414	        .identity
415	        .as_ref()
416	        .unwrap()
417	        .spki_sha256
418	        .clone();
419	    let body = serde_json::json!({ "code": code, "device_name": name, "spki_sha256": spki });
420	    let (status, reply) = call(port, "POST", "/api/v1/pair", None, &body.to_string());

