3539	            .last_draft_pass
3540	            .is_some_and(|t| t.elapsed() < DRAFT_PASS_EVERY)
3541	        {
3542	            return;
3543	        }
3544	        self.last_draft_pass = Some(Instant::now());
3545	        let editors = &self.ui_state.prompt_boxes.editors;
3546	        self.draft_marks.retain(|id, _| editors.contains_key(id));
3547	        let mut moved = Vec::new();
3548	        for (id, editor) in editors {
3549	            let mark = prompt_box::draft_mark(editor);
3550	            if self.draft_marks.get(id) != Some(&mark) {
3551	                self.draft_marks.insert(*id, mark);
3552	                moved.push(*id);
