243	/// One HTTP request over a fresh pinned TLS connection: the status and
244	/// the body.
245	fn http(
246	    addr: SocketAddr,
247	    config: &Arc<ClientConfig>,
248	    method: &str,
249	    path: &str,
250	    bearer: Option<&str>,
251	    body: &str,
252	) -> std::io::Result<(u16, String)> {
253	    let tcp = TcpStream::connect(addr)?;
254	    tcp.set_read_timeout(Some(Duration::from_secs(10)))?;
255	    let conn = ClientConnection::new(
256	        Arc::clone(config),
257	        ServerName::try_from("localhost").unwrap(),
258	    )
259	    .map_err(std::io::Error::other)?;
260	    let mut s = StreamOwned::new(conn, tcp);
261	    while s.conn.is_handshaking() {
262	        s.conn.complete_io(&mut s.sock)?;
263	    }
264	    let auth = bearer
265	        .map(|t| format!("Authorization: Bearer {t}\r\n"))
266	        .unwrap_or_default();
267	    write!(
268	        s,
269	        "{method} {path} HTTP/1.1\r\nHost: localhost\r\n{auth}Content-Length: {}\r\n\r\n{body}",
270	        body.len()
271	    )?;
272	    s.flush()?;
273	    let mut reader = BufReader::new(s);
274	    let mut line = String::new();
275	    reader.read_line(&mut line)?;
276	    let status: u16 = line
277	        .split_whitespace()
278	        .nth(1)
279	        .and_then(|s| s.parse().ok())
280	        .ok_or_else(|| std::io::Error::new(std::io::ErrorKind::InvalidData, line.clone()))?;
281	    let mut length = 0usize;
282	    loop {
283	        let mut h = String::new();
284	        reader.read_line(&mut h)?;
285	        let h = h.trim_end();
286	        if h.is_empty() {
287	            break;
288	        }
289	        if let Some(v) = h.strip_prefix("Content-Length:") {
290	            length = v.trim().parse().unwrap_or(0);
291	        }
292	    }
293	    let mut out = vec![0; length];
294	    reader.read_exact(&mut out)?;
295	    Ok((status, String::from_utf8_lossy(&out).into_owned()))
296	}
