298	/// A request from a client thread, served by the app on this thread.
299	fn call(
300	    port: &mut Port,
301	    method: &str,
302	    path: &str,
303	    bearer: Option<&str>,
304	    body: &str,
305	) -> (u16, serde_json::Value) {
306	    let addr = port.addr;
307	    let config = Arc::clone(&port.client);
308	    let (method, path, bearer, body) = (
309	        method.to_owned(),
310	        path.to_owned(),
311	        bearer.map(str::to_owned),
312	        body.to_owned(),
313	    );
314	    let client =
315	        std::thread::spawn(move || http(addr, &config, &method, &path, bearer.as_deref(), &body));
316	    let deadline = std::time::Instant::now() + Duration::from_secs(5);
317	    while !client.is_finished() {
318	        assert!(std::time::Instant::now() < deadline, "no reply");
319	        port.app.serve_pending();
320	        std::thread::sleep(Duration::from_millis(2));
321	    }
322	    let (status, text) = client.join().unwrap().expect("http");
323	    let value = serde_json::from_str(&text).unwrap_or_else(|e| panic!("{e}: {text}"));
324	    (status, value)
325	}
