1959	/// A subscription at `path`, for its query (`?scope=all`).
1960	fn subscribe_at(port: &mut Port, token: &str, path: &str) -> Subscriber {
1961	    let addr = port.addr;
1962	    let url = format!("wss://localhost{path}");
1963	    let config = Arc::clone(&port.client);
1964	    let token = token.to_owned();
1965	    let (tx, frames) = std::sync::mpsc::channel();
1966	    let (outbox, out_rx) = std::sync::mpsc::channel::<Out>();
1967	    let paused = Arc::new(std::sync::atomic::AtomicBool::new(false));
1968	    let hold = Arc::clone(&paused);
1969	    std::thread::spawn(move || {
1970	        let tcp = TcpStream::connect(addr).expect("connect");
1971	        let conn = ClientConnection::new(config, ServerName::try_from("localhost").unwrap())
1972	            .expect("client");
1973	        let mut s = StreamOwned::new(conn, tcp);
1974	        while s.conn.is_handshaking() {
1975	            s.conn.complete_io(&mut s.sock).expect("handshake");
1976	        }
1977	        let mut request = url.into_client_request().unwrap();
1978	        request
1979	            .headers_mut()
1980	            .insert("Authorization", format!("Bearer {token}").parse().unwrap());
1981	        let (mut ws, _) = match tungstenite::client(request, s) {
1982	            Ok(ok) => ok,
1983	            Err(e) => {
1984	                let _ = tx.send(Err(format!("upgrade refused: {e}")));
1985	                return;
1986	            }
1987	        };
1988	        // A short read timeout, so the outbox is looked at between
1989	        // frames; the library keeps a part-read frame across it.
1990	        ws.get_mut()
1991	            .sock
1992	            .set_read_timeout(Some(Duration::from_millis(20)))
1993	            .expect("timeout");
1994	        loop {
1995	            while hold.load(std::sync::atomic::Ordering::SeqCst) {
