/// The Remote devices dialog: opened from the settings menu, it shows
/// the host, opens a pairing window whose code it then shows, and
/// revokes a paired device; every change is an action.
#[test]
fn remote_devices_dialog_opens_pairing_and_revokes_a_device() {
    use switchboard::ports::remote::{Identity, Listen, PairedDevice, Scope};
    let (mut harness, _) = harness();
    let device = PairedDevice {
        id: uuid::Uuid::new_v4(),
        name: "Vision Pro".into(),
        scope: Scope::Read,
        token_sha256: "ab".repeat(32),
        created: at(0),
        last_seen: None,
    };
    harness.state_mut().dispatch(AppAction::IdentityLoaded {
        identity: Identity {
            schema_version: 1,
            server_id: uuid::Uuid::new_v4(),
            server_name: "Studio".into(),
            certificate: "MIIB".into(),
            spki_sha256: "cd".repeat(32),
            created: at(0),
            listen: Listen::default(),
        },
        devices: vec![device.clone()],
        rotated: false,
    });
    harness.state_mut().dispatched.clear();
    click(&mut harness, "Settings");
    click(&mut harness, "Remote devices…");
    harness.get_by_label("Remote devices");
    harness.get_by_label("Vision Pro");
    assert!(harness.query_by_label("Stop pairing").is_none());
    click(&mut harness, "Allow pairing for 5 minutes");
    let code = actions(&harness)
        .into_iter()
        .find_map(|a| match a {
            AppAction::OpenPairing { code, scope } => {
                assert_eq!(scope, Scope::Read);
                Some(code)
            }
            _ => None,
        })
        .expect("a pairing window was opened");
    assert_eq!(code.len(), 8);
    assert!(harness.state().core().pairing().is_some());
    // The code shows in two halves, as it is read aloud.
    let (a, b) = code.split_at(4);
    harness.get_by_label(format!("{a} {b}").as_str());
    // The window grew around the QR code; a frame settles its place
    // before the next click.
    harness.run_steps(2);
    // The clipboard command is in the click's own frame.
    harness.get_by_label("Copy invite").click();
    harness.step();
    let invite = harness
        .output()
        .platform_output
        .commands
        .iter()
        .find_map(|c| match c {
            egui::OutputCommand::CopyText(text) => Some(text.clone()),
            _ => None,
        })
        .expect("the invite went to the clipboard");
    let invite: serde_json::Value = serde_json::from_str(&invite).unwrap();
    assert_eq!(invite["code"], code);
    assert_eq!(
        invite["spki_sha256"],
        harness.state().core().identity().unwrap().spki_sha256
    );
    assert!(invite["addresses"].is_array());
    harness.run_steps(2);
    click(&mut harness, "Stop pairing");
    assert!(actions(&harness).contains(&AppAction::ClosePairing));
    assert!(harness.state().core().pairing().is_none());
    harness.run_steps(2);
    click(&mut harness, "Revoke");
    assert!(actions(&harness).contains(&AppAction::RevokeDevice(device.id)));
    assert!(harness.state().core().devices().is_empty());
    harness.get_by_label("No device is paired.");
    click(&mut harness, "Close");
    assert!(harness.state().ui_state.remote_dialog.is_none());
}

import Foundation

/// What `/info` says to anyone.
public struct ServerInfo: Decodable, Sendable, Equatable {
    public let serverID: ServerID
    public let serverName: String
    public let protocolVersion: Int
    public let capabilities: [String]
    public let spkiSha256: String
    public let limits: Limits
    public let pairingOpen: Bool
    /// The host app's version; a host older than this field has none.
    public let version: String?

    public struct Limits: Decodable, Sendable, Equatable {
        public let bodyBytes: Int
        public let stringBytes: Int
        public let notesBytes: Int
        public let screenLines: Int

        enum CodingKeys: String, CodingKey {
            case bodyBytes = "body_bytes"
            case stringBytes = "string_bytes"
            case notesBytes = "notes_bytes"
            case screenLines = "screen_lines"
        }
    }

    enum CodingKeys: String, CodingKey {
        case serverID = "server_id"
        case serverName = "server_name"
        case protocolVersion = "protocol"
        case capabilities
        case spkiSha256 = "spki_sha256"
        case limits
        case pairingOpen = "pairing_open"
        case version
    }
}

/// What a device may do with its token.
public enum Scope: String, Codable, Sendable {
    case read
    case control
}

/// `POST /pair`.
public struct PairRequest: Encodable, Sendable {
    public let code: String
    public let deviceName: String
    public let spkiSha256: String

    public init(code: String, deviceName: String, spkiSha256: String) {
        self.code = code
        self.deviceName = deviceName
        self.spkiSha256 = spkiSha256
    }

    enum CodingKeys: String, CodingKey {
        case code
        case deviceName = "device_name"
        case spkiSha256 = "spki_sha256"
    }
}

public struct PairReply: Decodable, Sendable {
    public let token: String
    public let scope: Scope
    public let serverID: ServerID
    public let deviceID: String

    enum CodingKeys: String, CodingKey {
        case token, scope
        case serverID = "server_id"
        case deviceID = "device_id"
    }
}

/// A host's key as both ends show it to the owner for a comparison by
/// eye: the first sixteen hex digits of the SPKI hash in groups of
/// four, as the host's pairing dialog prints them.
public enum KeyFingerprint {
    public static func short(_ hex: String) -> String {
        let digits = Array(hex.prefix(16))
        return stride(from: 0, to: digits.count, by: 4)
            .map { String(digits[$0..<min($0 + 4, digits.count)]) }
            .joined(separator: " ")
    }
}

/// What the host's QR code holds while its pairing window is open: the
/// installation, the key to pin before the code is sent, the code, and
/// where the host answered from. Also pasted by hand.
public struct PairingInvite: Decodable, Sendable, Equatable {
    public let serverID: ServerID
    public let spkiSha256: String
    public let code: String
    public let addresses: [String]

    enum CodingKeys: String, CodingKey {
        case serverID = "server_id"
        case spkiSha256 = "spki_sha256"
        case code, addresses
    }

    public init(serverID: ServerID, spkiSha256: String, code: String, addresses: [String]) {
        self.serverID = serverID
        self.spkiSha256 = spkiSha256
        self.code = code
        self.addresses = addresses
    }

    /// The invite from the scanned or pasted text.
    public static func parse(_ text: String) throws -> PairingInvite {
        try Wire.decode(PairingInvite.self, from: Data(text.utf8))
    }
}

