/// Write one JSON response on a kept connection. Head and body in one
/// write, so a reply is one TLS record and one segment. Every reply is
/// marked uncacheable and its type final, which no client reads and a
/// browser honours.
fn respond<W: Write>(
    w: &mut W,
    status: u16,
    headers: &[(&'static str, String)],
    body: &[u8],
) -> io::Result<()> {
    let mut head = String::new();
    for (name, value) in headers {
        let _ = write!(head, "{name}: {value}\r\n");
    }
    write_response(w, status, "application/json", &head, false, body)
}

/// Write one of the embedded pages and close the connection, so a
/// browser's load never holds one of the unauthenticated slots for the
/// idle timeout. The policy headers keep the page to its own files and
/// the host's own origin.
fn respond_page<W: Write>(w: &mut W, page: &web::Page) -> io::Result<()> {
    let head = format!(
        "Content-Security-Policy: {}\r\nReferrer-Policy: no-referrer\r\n",
        web::CONTENT_SECURITY_POLICY
    );
    write_response(w, 200, page.content_type, &head, true, page.body.as_bytes())
}

fn write_response<W: Write>(
    w: &mut W,
    status: u16,
    content_type: &str,
    extra: &str,
    close: bool,
    body: &[u8],
) -> io::Result<()> {
    let reason = match status {
        200 => "OK",
        400 => "Bad Request",
        401 => "Unauthorized",
        403 => "Forbidden",
        404 => "Not Found",
        405 => "Method Not Allowed",
        413 => "Content Too Large",
        429 => "Too Many Requests",
        503 => "Service Unavailable",
        504 => "Gateway Timeout",
        _ => "Error",
    };
    let connection = if close { "close" } else { "keep-alive" };
    let mut out = format!(
