:root {
  color-scheme: light dark;
  --fg: #1b1b1f;
  --bg: #ffffff;
  --muted: #6b6b73;
  --line: #d9d9de;
  --accent: #b45309;
  --accent-bg: #fff4e5;
}

@media (prefers-color-scheme: dark) {
  :root {
    --fg: #ececf1;
    --bg: #121216;
    --muted: #9a9aa4;
    --line: #2e2e36;
    --accent: #f59e0b;
    --accent-bg: #2a1e0a;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font: 16px/1.4 -apple-system, BlinkMacSystemFont, "Helvetica Neue", Helvetica, Arial, sans-serif;
  color: var(--fg);
  background: var(--bg);
}

header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 12px 16px;
  border-bottom: 1px solid var(--line);
  font-weight: 600;
}

main {
  padding: 12px 16px 48px;
  max-width: 720px;
  margin: 0 auto;
}

h1 {
  font-size: 20px;
  margin: 8px 0;
}

h2 {
  font-size: 14px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin: 20px 0 6px;
}

.meta {
  color: var(--muted);
  font-size: 14px;
  font-weight: 400;
}

.session-row {
  display: block;
  width: 100%;
  text-align: left;
  padding: 10px 12px;
  margin: 0 0 6px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--bg);
  color: var(--fg);
  font: inherit;
  cursor: pointer;
}

.session-row.is-waiting {
  border-color: var(--accent);
  background: var(--accent-bg);
}

.session-row .name {
  font-weight: 600;
}

.session-row .line {
  display: block;
}

.waiting {
  color: var(--accent);
  font-weight: 600;
}

pre {
  white-space: pre-wrap;
  word-break: break-word;
  font: 14px/1.4 ui-monospace, Menlo, Monaco, Consolas, monospace;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  overflow-x: auto;
  min-height: 3em;
}

textarea {
  width: 100%;
  font: inherit;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--bg);
  color: var(--fg);
}

button {
  font: inherit;
  padding: 8px 14px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--bg);
  color: var(--fg);
  cursor: pointer;
}

button:disabled {
  opacity: 0.5;
  cursor: default;
}

.row {
  display: flex;
  gap: 12px;
  align-items: center;
  margin-top: 8px;
}

nav {
  margin: 4px 0 12px;
}

