/// and scope, with the host's id and name. The page reads it to
/// know whether to show the reply box; no Swift client calls it.
fn remote_me(&self, device: &PairedDevice) -> RemoteReply {
    let identity = self.core.identity();
    let body = serde_json::json!({
        "device_id": device.id,
        "name": device.name,
        "scope": device.scope,
        "server_id": identity.map(|i| i.server_id),
        "server_name": identity.map(|i| i.server_name.clone()),
    });
    self.envelope(200, &body, true)
}

