use uuid::Uuid;

use super::action::PairingWindow;
use super::action::{AppAction, AppCore, Clock, Effect, Out, PAIRING_ATTEMPTS, PAIRING_WINDOW};
use crate::ports::remote::{Identity, PairedDevice, Scope};

/// A device's last-seen time is saved when it moved by at least this
/// much, so a polling device does not rewrite `devices.json` on every
/// request.
const LAST_SEEN_SAVE_INTERVAL_SECS: u64 = 300;

/// The URL the pairing window's QR code carries, which a phone's
/// browser opens: the page at the port, with the code, the key hash and
/// the server id in the fragment. A fragment is never sent in the
/// request, so a server the owner has not verified never sees the code
/// before the page compares the key. `address` is where the port
/// answers on the network; `None` when it answers this Mac alone, in
/// which case the URL names the loopback address.
#[must_use]
pub fn invite_url(
    identity: &Identity,
    window: &PairingWindow,
    address: Option<IpAddr>,
    port: u16,
) -> String {
    let at = SocketAddr::new(address.unwrap_or(IpAddr::from([127, 0, 0, 1])), port);
    format!(
        "https://{at}/#code={}&key={}&id={}",
        window.code, identity.spki_sha256, identity.server_id
    )
}

