            """
        XCTAssertEqual(try PairingInvite.parse(json), invite)
        XCTAssertEqual(try PairingInvite.parse("  \(url)\n"), invite, "pasted with whitespace")
        XCTAssertThrowsError(try PairingInvite.parse("https://192.168.1.9:43187/#key=ab&id=1"))
        XCTAssertThrowsError(try PairingInvite.parse("https://192.168.1.9:43187/?code=X&key=ab&id=1"))
        XCTAssertThrowsError(try PairingInvite.parse("not an invite"))
    }
}

