+    pub headers: Vec<(&'static str, String)>,
+}
+
+impl RemoteReply {
+    /// A JSON reply with no header of its own.
+    #[must_use]
+    pub fn new(status: u16, body: Vec<u8>, authenticated: bool) -> Self {
+        Self {
+            status,
+            body,
+            authenticated,
